import { randomUUID } from 'node:crypto';
import { digest, stripeSourceMetadata, woodLabels } from '../../src/lib/firewood/import-contract.ts';
export function fixture(quantity='full', stacking=false) {
 const uid=randomUUID(), tag=uid.replaceAll('-',''), prices={half:30000,full:45000,two:84000};
 const order={quantity,stacking,wood_cents:prices[quantity],delivery_cents:0,stacking_cents:stacking?15000:0,total_cents:prices[quantity]+(stacking?15000:0),currency:'usd',tax_assumption:'unresolved_test_only',terms_version:'firewood-checkout-test-2026-10-25',contact:{name:'Synthetic Firewood '+tag.slice(0,8),email:tag+'@example.invalid',phone:'2025550100',address:'100 Synthetic Way',address2:'',city:'Test City',state:'VA',postal:'22407',notes:'Synthetic local evidence only'}};
 // Different synthetic orders normally represent different customers.
 order.contact.phone='202'+String(parseInt(tag.slice(0,8),16)%10000000).padStart(7,'0');
 const input={contract:'firewood-test-import-v1',source_id:'website_local_test',account_id:'acct_localSynthetic',order_id:uid,attempt_id:randomUUID(),reference:'FW-TEST-'+tag.toUpperCase(),session_id:'cs_test_'+tag,snapshot_hash:digest(order),order};
 const metadata=stripeSourceMetadata(input),chargeId='ch_'+tag,intentId='pi_'+tag;
 const state={account:{id:input.account_id},session:{id:input.session_id,livemode:false,mode:'payment',client_reference_id:input.reference,metadata,status:'complete',payment_status:'paid',amount_total:order.total_cents,amount_subtotal:order.total_cents,currency:'usd',total_details:{amount_discount:0,amount_shipping:0,amount_tax:0},automatic_tax:{enabled:false},customer_details:{email:order.contact.email},payment_intent:intentId,line_items:{has_more:false,data:[{quantity:1,currency:'usd',amount_subtotal:order.wood_cents,amount_total:order.wood_cents,amount_discount:0,amount_tax:0,price:{unit_amount:order.wood_cents,product:{name:woodLabels[quantity]+' of firewood — delivery included'}}},...(stacking?[{quantity:1,currency:'usd',amount_subtotal:15000,amount_total:15000,amount_discount:0,amount_tax:0,price:{unit_amount:15000,product:{name:'Stacking — one charge per delivery'}}}]:[])]}},intent:{id:intentId,livemode:false,currency:'usd',amount:order.total_cents,amount_received:order.total_cents,status:'succeeded',metadata,shipping:{name:order.contact.name,phone:order.contact.phone,address:{line1:order.contact.address,line2:order.contact.address2,city:order.contact.city,state:'VA',postal_code:'22407',country:'US'}},latest_charge:{id:chargeId,livemode:false,payment_intent:intentId,amount:order.total_cents,amount_captured:order.total_cents,currency:'usd',paid:true,captured:true,status:'succeeded',created:Math.floor(Date.now()/1000)-30,amount_refunded:0,disputed:false}},refunds:[],disputes:[]};
 const calls=[];
 const get=(path,value)=>async()=>{calls.push(path);if(state.outage)throw Error('synthetic unavailable');return structuredClone(value());};
 const stripe={accounts:{retrieve:get('GET account',()=>state.account)},checkout:{sessions:{retrieve:get('GET session',()=>state.session)}},paymentIntents:{retrieve:get('GET payment_intent',()=>state.intent)},refunds:{list:get('GET refunds',()=>({data:state.refunds,has_more:false}))},disputes:{list:get('GET disputes',()=>({data:state.disputes,has_more:false}))}};
 return {input,state,stripe,calls};
}
export function refund(f, amount, status='succeeded') {return {id:'re_'+randomUUID().replaceAll('-',''),charge:f.state.intent.latest_charge.id,payment_intent:f.state.intent.id,currency:'usd',amount,status,created:Math.floor(Date.now()/1000)-10};}
export function dispute(f, status='needs_response') {return {id:'du_'+randomUUID().replaceAll('-',''),charge:f.state.intent.latest_charge.id,payment_intent:f.state.intent.id,currency:'usd',amount:f.input.order.total_cents,status,livemode:false};}
